mapper.select:
SELECT t.id AS pick_item_id, t.picked_qty, t.qty, t2.house_code, t2.location_code, t.material_id, t.container_code, t.business_id, t8.inner_no businessNo, t.business_type, t.business_item_id, t7.depth_value, t8.customer_code, t8.create_time as 'waveTime' FROM wms_pick_item t LEFT JOIN wms_container t2 ON t2.code = t.container_code LEFT JOIN wms_outbound t3 ON t3.id = t.outbound_id LEFT JOIN wms_storage_location t4 ON t4.loc_no = t2.location_code LEFT JOIN wms_roadway t5 ON t4.rela_roadway_id = t5.id LEFT JOIN wms_storage_location_occupy t6 ON t6.parent_id = t4.id LEFT JOIN wms_warehouse_row t7 ON t7.id = t4.row_id LEFT JOIN wms_inventory_requisition_order t8 ON t.business_id = t8.id WHERE t4.loc_type = 'cubic' AND t6.id is not null AND (t5.is_enable = 0 OR t5.is_enable is null) AND (t3.state NOT IN ('creating', 'outbounding') OR t.outbound_id IS NULL) AND t.state = 'created'
AND t4.house_code = #{dto.houseCode}
ORDER BY t.create_time

SELECT t.id AS pick_item_id, t.pick_order_id, t.picked_qty, t2.house_code, t2.location_code, t.material_id, t.container_code, t3.exit_location, t4.inner_no orderNo, t4.create_time as 'waveTime' FROM wms_pick_item t LEFT JOIN wms_container t2 ON t2.code = t.container_code LEFT JOIN wms_outbound t3 ON t3.id = t.outbound_id LEFT JOIN wms_inventory_requisition_order t4 ON t4.id = t.business_id WHERE 1=1
AND t.state in
#{state}
AND t3.state in
#{status}
AND t.id = #{dto.pickItemId}
AND t.container_code = #{dto.containerCode}
AND t.pick_station = #{dto.outStationCode}
AND t4.inner_no = #{dto.orderNo}
AND t4.inner_no in
#{orderNo}
ORDER BY t.create_time

SELECT t4.house_code, t2.location_code, t.container_code, t.warehouse_location outboundLocationCode, t.exit_location, t.external_no orderNo, t.type as 'outboundType', t7.depth_value, CASE WHEN t.wave_time IS NOT NULL THEN t.wave_time ELSE t.create_time END AS waveTime, CASE WHEN t.wave_time IS NOT NULL THEN t.wave_time ELSE t.create_time END AS waveSendWcsTime FROM wms_outbound t LEFT JOIN wms_container t2 ON t2.code = t.container_code LEFT JOIN wms_storage_location t4 ON t4.loc_no = t2.location_code LEFT JOIN wms_roadway t5 ON t4.rela_roadway_id = t5.id LEFT JOIN wms_storage_location_occupy t6 ON t6.parent_id = t4.id LEFT JOIN wms_warehouse_row t7 ON t7.id = t4.row_id WHERE t4.loc_type = 'cubic' AND t6.id is not null AND t.type != 'm_out' AND (t5.is_enable = 0 OR t5.is_enable is null)
AND t.state in
#{status}
AND t.exit_location in
#{stationCode}
AND t.exit_location not in
#{stationCode}
AND t4.house_code = #{dto.houseCode}
ORDER BY t.create_time

