UPDATE wms_pick_item
SET outbound_id = #{outboundOrderId},
    pick_station      = #{pickStation}
WHERE id = #{pickItemId}

mapper.select:
SELECT pick_station as workstationCode, COUNT(*) as taskNum FROM (SELECT pick_station, container_code FROM wms_pick_item WHERE pick_station IN
#{code}
AND state = 'created' GROUP BY pick_station, container_code) t GROUP BY pick_station
